import { GoogleGenAI, Type } from "@google/genai";
import { HealthMetrics, PredictionInsight } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeHealthTrends(metricsHistory: HealthMetrics[]): Promise<PredictionInsight> {
  const modelName = 'gemini-3-flash-preview';

  const prompt = `
    Analyze the following 24-hour health telemetry data for a diabetic patient.
    Data: ${JSON.stringify(metricsHistory)}

    Detect potential anomalies (e.g., hypoglycemia, tachycardia, hypoxia).
    Predict the risk for the next 24 hours.
    Provide actionable medical recommendations.
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            riskLevel: { type: Type.STRING, description: "Risk assessment level" },
            summary: { type: Type.STRING, description: "Short summary of findings" },
            recommendation: { type: Type.STRING, description: "Medical advice for the patient" },
            anomaliesDetected: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["riskLevel", "summary", "recommendation", "anomaliesDetected"]
        }
      }
    });

    const text = response.text;
    return JSON.parse(text) as PredictionInsight;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      riskLevel: 'Moderate',
      summary: 'Automated analysis currently unavailable. Baseline monitoring active.',
      recommendation: 'Please maintain regular medication schedule and contact clinic if symptoms persist.',
      anomaliesDetected: []
    };
  }
}

import { useState, useEffect, useRef } from 'react';
import { HealthMetrics } from '../types';

export function useHealthData() {
  const [currentMetrics, setCurrentMetrics] = useState<HealthMetrics>({
    heartRate: 72,
    spO2: 98,
    temperature: 98.6,
    glucose: 110,
    timestamp: new Date().toISOString()
  });

  const [history, setHistory] = useState<HealthMetrics[]>([]);
  const intervalRef = useRef<number | null>(null);

  useEffect(() => {
    // Generate realistic fluctuating data
    intervalRef.current = window.setInterval(() => {
      setCurrentMetrics(prev => {
        const next = {
          heartRate: Math.max(60, Math.min(100, prev.heartRate + (Math.random() * 4 - 2))),
          spO2: Math.max(92, Math.min(100, prev.spO2 + (Math.random() * 0.4 - 0.2))),
          temperature: Math.max(97.5, Math.min(100.4, prev.temperature + (Math.random() * 0.2 - 0.1))),
          glucose: Math.max(80, Math.min(220, prev.glucose + (Math.random() * 10 - 5))),
          timestamp: new Date().toISOString()
        };

        setHistory(h => [...h.slice(-49), next]); // Keep last 50 readings
        return next;
      });
    }, 2000);

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, []);

  return { currentMetrics, history };
}

