import { GoogleGenAI, Type } from "@google/genai";
import { HealthMetrics, PredictionInsight } from "../types";

// Always use the named parameter and process.env.API_KEY directly for initialization
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeHealthTrends(metricsHistory: HealthMetrics[]): Promise<PredictionInsight> {
  // Use gemini-3-pro-preview for complex medical telemetry reasoning and anomaly detection
  const modelName = 'gemini-3-pro-preview';

  const prompt = `
    Analyze the following 24-hour health telemetry data for a diabetic patient.
    Data: ${JSON.stringify(metricsHistory)}

    Detect potential anomalies (e.g., hypoglycemia, tachycardia, hypoxia).
    Predict the risk for the next 24 hours.
    Provide actionable medical recommendations. Return valid JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            riskLevel: { 
              type: Type.STRING,
              description: "The calculated risk level: Low, Moderate, High, or Critical"
            },
            summary: { 
              type: Type.STRING,
              description: "A clinical summary of detected patterns and telemetry trends"
            },
            recommendation: { 
              type: Type.STRING,
              description: "Specific actionable medical advice for the patient"
            },
            anomaliesDetected: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "List of specific medical anomalies identified from the data"
            }
          },
          required: ["riskLevel", "summary", "recommendation", "anomaliesDetected"]
        }
      }
    });

    // Access the .text property directly as it returns the string output (do not call as a method)
    const text = response.text;
    if (!text) throw new Error("Empty response from AI engine");

    return JSON.parse(text.trim()) as PredictionInsight;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    // Graceful fallback for reliability in medical applications
    return {
      riskLevel: 'Moderate',
      summary: 'Automated AI analysis is currently offline. Local thresholding is active.',
      recommendation: 'Monitor glucose closely and follow standard insulin protocol until sync is restored.',
      anomaliesDetected: ["AI System Sync Delay"]
    };
  }
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Activity, 
  Heart, 
  Thermometer, 
  Droplets, 
  ShieldCheck, 
  Bell, 
  Settings, 
  AlertTriangle,
  Zap,
  Cpu,
  RefreshCw,
  Info
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Legend 
} from 'recharts';
import { useHealthData } from './hooks/useHealthData';
import { analyzeHealthTrends } from './services/geminiService';
import { PredictionInsight } from './types';
import MetricCard from './components/MetricCard';

const App: React.FC = () => {
  const { currentMetrics, history } = useHealthData();
  const [insight, setInsight] = useState<PredictionInsight | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [activeTab, setActiveTab] = useState<'overview' | 'trends' | 'edge'>('overview');

  const fetchAiInsight = async () => {
    if (history.length < 5) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeHealthTrends(history);
      setInsight(result);
    } catch (err) {
      console.error("Insight Fetch Error", err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    const interval = setInterval(fetchAiInsight, 30000);
    fetchAiInsight();
    return () => clearInterval(interval);
  }, [history.length > 10]);

  const riskColor = useMemo(() => {
    switch (insight?.riskLevel) {
      case 'Critical': return 'text-rose-600 bg-rose-50 border-rose-200';
      case 'High': return 'text-amber-600 bg-amber-50 border-amber-200';
      case 'Moderate': return 'text-blue-600 bg-blue-50 border-blue-200';
