          >
            <Activity size={20} />
            <span className="font-semibold">Dashboard</span>
          </button>
          <button 
            onClick={() => setActiveTab('trends')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-colors ${activeTab === 'trends' ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <RefreshCw size={20} />
