    import { GoogleGenAI, Type } from "@google/genai";
    import { HealthMetrics, PredictionInsight } from "../types";

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    export async function analyzeHealthTrends(metricsHistory: HealthMetrics[]): Promise<PredictionInsight> {
      const modelName = 'gemini-3-flash-preview';

      const prompt = `
        Analyze the following 24-hour health telemetry data for a diabetic patient.
        Data: ${JSON.stringify(metricsHistory)}

        Detect potential anomalies (e.g., hypoglycemia, tachycardia, hypoxia).
        Predict the risk for the next 24 hours.
        Provide actionable medical recommendations.
      `;

      try {
        const response = await ai.models.generateContent({
          model: modelName,
          contents: prompt,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.OBJECT,
              properties: {
                riskLevel: { type: Type.STRING, description: "Risk assessment level" },
                summary: { type: Type.STRING, description: "Short summary of findings" },
                recommendation: { type: Type.STRING, description: "Medical advice for the patient" },
                anomaliesDetected: {
                  type: Type.ARRAY,
                  items: { type: Type.STRING }
                }
              },
              required: ["riskLevel", "summary", "recommendation", "anomaliesDetected"]
            }
          }
        });

        const text = response.text;
        return JSON.parse(text) as PredictionInsight;
      } catch (error) {
        console.error("Gemini Analysis Error:", error);
        return {
          riskLevel: 'Moderate',
          summary: 'Automated analysis currently unavailable. Baseline monitoring active.',
          recommendation: 'Please maintain regular medication schedule and contact clinic if symptoms persist.',
          anomaliesDetected: []
        };
      }
    }
