import { GoogleGenAI, Type } from "@google/genai";
import { HealthMetrics, PredictionInsight } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzePatientData(history: HealthMetrics[]): Promise<PredictionInsight> {
  const prompt = `
    TASK: Medical Telemetry Trend Analysis for Home Monitoring.
    DATA: ${JSON.stringify(history.slice(-20))}

    INSTRUCTIONS:
    1. Identify risk level (Low, Moderate, High, Critical).
    2. Detect anomalies in Glucose (Hypo/Hyperglycemia), Heart Rate (Brady/Tachycardia), or Oxygen.
    3. Provide 1 concise medical recommendation.
    4. Respond ONLY in JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            riskLevel: { type: Type.STRING },
            summary: { type: Type.STRING },
            recommendation: { type: Type.STRING },
            anomaliesDetected: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["riskLevel", "summary", "recommendation", "anomaliesDetected"]
        }
      }
    });

    return JSON.parse(response.text) as PredictionInsight;
  } catch (err) {
    console.error("AI Insight Error:", err);
    return {
      riskLevel: "Low",
      summary: "Monitoring stable. No critical anomalies detected in current window.",
      recommendation: "Continue regular activity and monitoring.",
      anomaliesDetected: []
    };
  }
}

