export interface HealthMetrics {
  heartRate: number;
  spO2: number;
  temperature: number;
  glucose: number;
  timestamp: string;
}

export interface PredictionInsight {
  riskLevel: 'Low' | 'Moderate' | 'High' | 'Critical';
  summary: string;
  recommendation: string;
  anomaliesDetected: string[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { HealthMetrics, PredictionInsight } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeHealthTrends(history: HealthMetrics[]): Promise<PredictionInsight> {
  const model = "gemini-3-flash-preview";

  const prompt = `
    As the HomeHealth Guardian AI, analyze the following 24-hour health telemetry for a diabetic patient.
    Identify any anomalies (hypoglycemia, tachycardia, fever, etc.) and predict risks for the next 24 hours.

    Data: ${JSON.stringify(history)}

    Return a structured JSON analysis.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            riskLevel: { type: Type.STRING, enum: ['Low', 'Moderate', 'High', 'Critical'] },
            summary: { type: Type.STRING },
            recommendation: { type: Type.STRING },
            anomaliesDetected: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["riskLevel", "summary", "recommendation", "anomaliesDetected"]
        }
      }
    });

    return JSON.parse(response.text) as PredictionInsight;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      riskLevel: 'Low',
      summary: 'Unable to process AI prediction at this moment. Sensors indicate stable baseline.',
      recommendation: 'Check sensor connectivity and maintain current routine.',
      anomaliesDetected: []
    };
  }
}

import { useState, useEffect } from 'react';
import { HealthMetrics } from '../types';

export function useHealthData() {
  const [history, setHistory] = useState<HealthMetrics[]>([]);
  const [currentMetrics, setCurrentMetrics] = useState<HealthMetrics>({
    heartRate: 72,
    spO2: 98,
    temperature: 98.6,
    glucose: 110,
    timestamp: new Date().toISOString()
  });

  useEffect(() => {
    // Generate some initial data
    const initial = Array.from({ length: 24 }).map((_, i) => ({
      heartRate: 70 + Math.random() * 10,
      spO2: 97 + Math.random() * 2,
      temperature: 98 + Math.random(),
      glucose: 100 + Math.random() * 40,
      timestamp: new Date(Date.now() - (24 - i) * 3600000).toISOString()
    }));
    setHistory(initial);

    const interval = setInterval(() => {
      const newMetric = {
        heartRate: 70 + Math.random() * 15,
        spO2: 96 + Math.random() * 4,
        temperature: 98 + Math.random() * 1.5,
        glucose: 100 + Math.random() * 60,
        timestamp: new Date().toISOString()
      };
      setCurrentMetrics(newMetric);
      setHistory(prev => [...prev.slice(-48), newMetric]);
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  return { currentMetrics, history };
}

