            className={`w-full flex items-center justify-between px-4 py-3.5 rounded-2xl transition-all ${activeTab === 'overview' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-500 hover:bg-slate-50 hover:text-indigo-600'}`}
          >
            <div className="flex items-center gap-3">
              <Activity size={20} />
              <span className="font-bold text-sm">Dashboard</span>
            </div>
            {activeTab === 'overview' && <ChevronRight size={14} />}
          </button>
          <button 
            onClick={() => setActiveTab('trends')}
            className={`w-full flex items-center justify-between px-4 py-3.5 rounded-2xl transition-all ${activeTab === 'trends' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-500 hover:bg-slate-50 hover:text-indigo-600'}`}
          >
            <div className="flex items-center gap-3">
              <RefreshCw size={20} />
              <span className="font-bold text-sm">Vital Trends</span>
            </div>
            {activeTab === 'trends' && <ChevronRight size={14} />}
          </button>
          <button 
            onClick={() => setActiveTab('edge')}
            className={`w-full flex items-center justify-between px-4 py-3.5 rounded-2xl transition-all ${activeTab === 'edge' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-500 hover:bg-slate-50 hover:text-indigo-600'}`}
          >
            <div className="flex items-center gap-3">
              <Cpu size={20} />
              <span className="font-bold text-sm">Edge Nodes</span>
            </div>
            {activeTab === 'edge' && <ChevronRight size={14} />}
          </button>
        </nav>

        <div className="pt-6 border-t border-slate-100">
          <button className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-slate-50 text-slate-500 rounded-xl font-bold text-xs hover:bg-slate-100 transition-colors">
            <Settings size={14} />
            System Settings
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-4 lg:p-10 max-w-7xl mx-auto w-full">
        <header className="flex justify-between items-start mb-10">
          <div>
            <h2 className="text-3xl font-extrabold text-slate-800 tracking-tight">Active Monitoring</h2>
            <div className="flex items-center gap-2 mt-1">
              <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              <p className="text-slate-500 text-xs font-semibold uppercase tracking-wider">Edge Hub Connected • #4412-BENGALURU</p>
            </div>
          </div>
          <div className="flex gap-3">
            <button className="p-3 bg-white border border-slate-200 rounded-2xl shadow-sm hover:shadow-md transition-all relative group">
              <Bell size={22} className="text-slate-500 group-hover:text-indigo-600" />
              <div className="absolute top-3 right-3 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white"></div>
            </button>
          </div>
        </header>

        {activeTab === 'overview' && (
          <div className="space-y-8">
            {/* Real-time Metric Cards */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
              <MetricCard 
                label="Glucose Level" 
                value={Math.round(currentMetrics.glucose)} 
                unit="mg/dL" 
                color="text-emerald-500"
                data={history}
                dataKey="glucose"
                icon={<Droplets size={24} className="text-emerald-500" />}
              />
              <MetricCard 
                label="Heart Rate" 
                value={Math.round(currentMetrics.heartRate)} 
                unit="BPM" 
                color="text-rose-500"
                data={history}
                dataKey="heartRate"
                icon={<Heart size={24} className="text-rose-500" />}
              />
              <MetricCard 
                label="SpO2 Saturation" 
                value={currentMetrics.spO2.toFixed(1)} 
                unit="%" 
                color="text-blue-500"
                data={history}
                dataKey="spO2"
                icon={<Activity size={24} className="text-blue-500" />}
              />
              <MetricCard 
                label="Body Temp" 
                value={currentMetrics.temperature.toFixed(1)} 
                unit="°F" 
                color="text-amber-500"
                data={history}
                dataKey="temperature"
                icon={<Thermometer size={24} className="text-amber-500" />}
              />
            </div>

            {/* AI Insight & Main Telemetry Chart */}
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
              {/* Guardian AI Prediction Panel */}
              <div className={`xl:col-span-1 rounded-[2.5rem] p-8 border shadow-sm transition-all duration-700 ${riskStyles.bg} ${riskStyles.border}`}>
                <div className="flex items-center justify-between mb-8">
                  <div className="flex items-center gap-3">
                    <div className="p-3 bg-white rounded-2xl shadow-sm">
                      <Zap size={20} className={riskStyles.accent} />
                    </div>
                    <h3 className={`font-black uppercase tracking-widest text-[10px] ${riskStyles.text}`}>Guardian AI Agent</h3>
                  </div>
                  {isAnalyzing && <RefreshCw size={18} className="animate-spin text-slate-400" />}
                </div>

                {insight ? (
                  <div className="space-y-6 flex-1 flex flex-col">
                    <div>
                      <div className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-1">24h Risk Forecast</div>
                      <div className={`text-2xl font-black flex items-center gap-3 ${riskStyles.text}`}>
                        {insight.riskLevel} Risk
                        {insight.riskLevel !== 'Low' && <AlertTriangle size={24} className="animate-bounce" />}
                      </div>
                    </div>

                    <p className={`text-sm leading-relaxed font-bold opacity-80 ${riskStyles.text}`}>
                      {insight.summary}
                    </p>

                    <div>
                      <div className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-3">Detected Anomalies</div>
                      <div className="flex flex-wrap gap-2">
                        {insight.anomaliesDetected.length > 0 ? insight.anomaliesDetected.map((a, i) => (
                          <span key={i} className={`px-3 py-1.5 rounded-xl bg-white text-[10px] font-black border border-current/10 shadow-sm ${riskStyles.text}`}>{a}</span>
                        )) : <span className="text-xs font-bold italic opacity-60">No critical events in current window</span>}
                      </div>
                    </div>

                    <div className="pt-6 mt-auto border-t border-current/10">
                      <div className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-2">Primary Recommendation</div>
                      <div className="p-4 bg-white/40 rounded-2xl border border-white">
                        <p className={`text-xs font-black italic ${riskStyles.text}`}>"{insight.recommendation}"</p>
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center flex-1 py-16 text-center">
                    <div className="w-16 h-16 bg-white rounded-3xl flex items-center justify-center mb-4 shadow-sm">
                      <RefreshCw className="animate-spin text-indigo-200" size={32} />
                    </div>
                    <p className="text-sm font-black text-slate-400 uppercase tracking-widest">Synthesizing Edge Logs</p>
                  </div>
                )}
              </div>

              {/* High-Resolution Telemetry Graph */}
              <div className="xl:col-span-2 bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100">
                <div className="flex justify-between items-center mb-8">
                  <div>
                    <h3 className="text-lg font-black text-slate-800">Longitudinal Telemetry</h3>
                    <p className="text-xs font-bold text-slate-400">Past 24 Hours • Continuous Streaming</p>
                  </div>
                  <div className="flex gap-4">
                    <div className="flex items-center gap-2">
                      <div className="w-3 h-3 rounded-full bg-emerald-500 shadow-sm shadow-emerald-100"></div>
                      <span className="text-[10px] font-black text-slate-400 uppercase">Glucose</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <div className="w-3 h-3 rounded-full bg-rose-500 shadow-sm shadow-rose-100"></div>
                      <span className="text-[10px] font-black text-slate-400 uppercase">Heart Rate</span>
                    </div>
                  </div>
                </div>
                <div className="h-[320px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={history}>
                      <CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="timestamp" hide />
                      <YAxis yAxisId="left" stroke="#cbd5e1" fontSize={10} tickLine={false} axisLine={false} />
                      <YAxis yAxisId="right" orientation="right" stroke="#cbd5e1" fontSize={10} tickLine={false} axisLine={false} />
                      <Tooltip 
                        contentStyle={{ borderRadius: '1.25rem', border: 'none', boxShadow: '0 15px 30px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                        cursor={{ stroke: '#6366f1', strokeWidth: 2, strokeDasharray: '4 4' }}
                      />
                      <Line yAxisId="left" type="monotone" dataKey="glucose" stroke="#10b981" strokeWidth={5} dot={false} animationDuration={500} />
                      <Line yAxisId="right" type="monotone" dataKey="heartRate" stroke="#f43f5e" strokeWidth={5} dot={false} animationDuration={500} />
                    </LineChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* ... (other tabs remain conceptually similar but fixed) ... */}
        {activeTab === 'trends' && (
          <div className="bg-white rounded-[2.5rem] p-16 border border-slate-100 min-h-[500px] flex flex-col items-center justify-center text-center shadow-inner">
            <div className="w-24 h-24 bg-slate-50 rounded-[2rem] flex items-center justify-center mb-8 text-slate-300">
              <RefreshCw size={48} strokeWidth={1.5} />
            </div>
            <h3 className="text-2xl font-black text-slate-800">Advanced Analytics Engine</h3>
            <p className="text-slate-500 max-w-sm mt-4 font-bold text-sm leading-relaxed uppercase tracking-wider">RESTRICTED ACCESS • CLINICAL VERIFICATION REQUIRED</p>
            <p className="text-slate-400 text-xs mt-2 max-w-xs">Detailed patient report generation and multi-sensor correlation matrices are available only to authorized medical practitioners.</p>
            <button className="mt-10 px-10 py-4 bg-indigo-600 text-white rounded-[1.5rem] font-black text-xs uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Request Professional Audit</button>
          </div>
        )}

        {activeTab === 'edge' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm hover:shadow-md transition-all">
              <div className="flex justify-between items-start mb-8">
                <div className="p-4 bg-indigo-50 rounded-2xl text-indigo-600 shadow-sm shadow-indigo-50">
                  <Cpu size={28} />
                </div>
                <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-emerald-50 border border-emerald-100 text-emerald-600 text-[10px] font-black uppercase tracking-widest">
                  <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                  Online
                </div>
              </div>
              <h3 className="text-xl font-black text-slate-800">RPi 5 Core Hub</h3>
              <p className="text-[10px] font-black text-slate-400 mt-1 uppercase tracking-widest">Serial: #HH-EDGE-4412-BENG</p>

              <div className="mt-10 space-y-5">
                <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest">
                  <span className="text-slate-300">Inference Load</span>
                  <span className="text-slate-800">14%</span>
                </div>
                <div className="w-full h-2 bg-slate-50 rounded-full overflow-hidden shadow-inner">
                  <div className="h-full bg-indigo-500 w-[14%] rounded-full shadow-lg shadow-indigo-200"></div>
                </div>
                <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest pt-2">
                  <span className="text-slate-300">Last Telemetry</span>
                  <span className="text-slate-800">Just Now</span>
                </div>
              </div>
            </div>
            {/* ... other nodes ... */}
          </div>
        )}
      </main>

      {/* Mobile Navigation Dock */}
      <nav className="lg:hidden fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 flex justify-around p-4 pb-10 z-[100]">
        {[
          { id: 'overview', icon: Activity, label: 'Dash' },
          { id: 'trends', icon: RefreshCw, label: 'Vitals' },
          { id: 'edge', icon: Cpu, label: 'Nodes' },
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)} 
            className={`flex flex-col items-center gap-1.5 transition-all ${activeTab === tab.id ? 'text-indigo-600 scale-110' : 'text-slate-300'}`}
          >
            <tab.icon size={22} strokeWidth={activeTab === tab.id ? 3 : 2} />
            <span className="text-[9px] font-black uppercase tracking-tighter">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;
